return $input.all().map(item => {
  const d = item.json;
  let title = String(d.title || '');
  let company = '';
  const at = title.lastIndexOf(' at ');
  if (at > -1) { company = title.slice(at + 4).trim(); title = title.slice(0, at).trim(); }
  const desc = String(d.content || d['content:encoded'] || d.contentSnippet || '');
  const cats = Array.isArray(d.categories) ? d.categories : (d.categories ? [d.categories] : []);
  return {
    json: {
      job_title: title,
      company,
      job_url: d.link || d.guid || '',
      source: 'Remote OK',
      location_text: cats.filter(c => /remote|world|global|anywhere/i.test(c)).join(', ') || '',
      salary: '',
      description: desc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
      posted_date: d.isoDate || d.pubDate || new Date().toISOString(),
      tags: cats.join(', '),
      job_id: d.guid || d.link || '',
      date_found: new Date().toISOString()
    }
  };
}).filter(i => i.json.job_url && i.json.job_title);

const data = $input.first().json;
const jobs = data.jobs || [];
return jobs.map(j => ({
  json: {
    job_title: j.title || '',
    company: j.company_name || '',
    job_url: j.url || '',
