const raw = $input.first().json;
const jobs = raw.jobs || (Array.isArray(raw) ? raw : []);
return jobs.map(j => {
  const co = j.company || {};
  const sal = (j.minSalary && j.maxSalary) ? `$${j.minSalary} - $${j.maxSalary}` : (j.salaryRange || '');
