  return {
    json: {
      job_title: j.title || j.role || '',
      company: co.name || co || '',
      job_url: j.applicationUrl || `https://himalayas.app/jobs/${j.slug}` || '',
      source: 'Himalayas',
      location_text: loc,
      salary: sal,
      description: (j.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
      posted_date: j.createdAt || new Date().toISOString(),
      tags: Array.isArray(j.categories) ? j.categories.join(', ') : '',
      job_id: j.slug || String(j.id || ''),
      date_found: new Date().toISOString()
    }
  };
}).filter(i => i.json.job_url && i.json.job_title);

