// YC Work at a Startup — returns HTML; extract structured data if available
// If the API returns JSON jobs array, parse it; otherwise return empty
const raw = $input.first().json;
const jobs = raw.jobs || raw.jobListings || (Array.isArray(raw) ? raw : []);
if (!jobs.length) return [];
return jobs.map(j => ({
  json: {
    job_title: j.title || j.role || '',
    company: j.company_name || (j.company && j.company.name) || '',
    job_url: j.url || `https://www.workatastartup.com/jobs/${j.id}` || '',
    source: 'YC Work at a Startup',
    location_text: j.locations || j.location || 'Remote',
    salary: j.salary || '',
    description: (j.description || j.body || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
    posted_date: j.created_at || new Date().toISOString(),
    tags: '',
    job_id: String(j.id || ''),
    date_found: new Date().toISOString()
  }
})).filter(i => i.json.job_url && i.json.job_title);

