// Otta requires authentication. Configure with your Otta API token.
// Set header: Authorization: Bearer YOUR_OTTA_TOKEN
const raw = $input.first().json;
const jobs = raw.jobs || raw.results || (Array.isArray(raw) ? raw : []);
if (!jobs.length) return [];
return jobs.map(j => ({
  json: {
    job_title: j.title || j.function || '',
    company: j.company ? (j.company.name || '') : '',
    job_url: j.url || `https://app.otta.com/jobs/${j.id}` || '',
    source: 'Otta',
    location_text: j.locations ? j.locations.join(', ') : 'Remote',
    salary: j.salary ? `$${j.salary.minimum} - $${j.salary.maximum}` : '',
    description: (j.jobDescription || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(),
    posted_date: j.created_at || new Date().toISOString(),
    tags: '',
    job_id: String(j.id || ''),
    date_found: new Date().toISOString()
  }
})).filter(i => i.json.job_url && i.json.job_title);

const keywords = [
  'async remote','asynchronous remote','worldwide remote','global remote',
  'work from anywhere','remote data analyst','remote data scientist',
  'remote ai marketing','remote marketing analyst','remote growth analyst',
  'remote bi analyst','remote automation specialist','remote ai workflow',
  'data analyst','data scientist','junior data scientist','bi analyst',
  'business intelligence','marketing analyst','growth analyst',
  'performance marketing','ai marketing','automation specialist',
  'ai workflow consultant','creative strategist','martech analyst',
  'machine learning','ml engineer','analytics engineer'
];
return $input.all().filter(item => {
  const text = [
    item.json.job_title || '',
    item.json.description || '',
    item.json.tags || ''
  ].join(' ').toLowerCase();
  return keywords.some(kw => text.includes(kw));
});

// Build sets from existing Google Sheets data
const existingUrls = new Set();
const existingKeys = new Set();
try {
  const existing = $('Get Existing URLs').all();
  for (const item of existing) {
    if (item.json.job_url) existingUrls.add(String(item.json.job_url).trim());
    if (item.json.company && item.json.job_title) {
      existingKeys.add(`${item.json.company}|${item.json.job_title}`.toLowerCase().trim());
    }
  }
} catch(e) { /* First run - sheet may be empty */ }

const seen = new Set();
const unique = [];
for (const item of $input.all()) {
  const job = item.json;
  const url = String(job.job_url || '').trim();
  const key = `${job.company}|${job.job_title}`.toLowerCase().trim();
  if (url && existingUrls.has(url)) continue;
  if (existingKeys.has(key)) continue;
  if (url && seen.has(url)) continue;
  if (seen.has(key)) continue;
  if (url) seen.add(url);
  seen.add(key);
  unique.push(item);
}
return unique;

const REJECT = [
  /\bus[\s-]?only\b/i, /\busa[\s-]?only\b/i, /\bunited[\s-]?states[\s-]?only\b/i,
  /\bcanada[\s-]?only\b/i, /\buk[\s-]?only\b/i, /\bunited[\s-]?kingdom[\s-]?only\b/i,
  /\beu[\s-]?only\b/i, /\beurope[\s-]?only\b/i, /\baustralia[\s-]?only\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i, /\bmust be located in\b/i,
  /\bmust be authorized to work in\b/i, /\bauthorized to work in the\b/i,
  /\bwork permit required\b/i, /\blocal residents only\b/i,
  /\bhybrid\b/i, /\bonsite\b/i, /\bon-site\b/i, /\boffice required\b/i,
  /\bin.?office\b/i,
  /\bremote (in|within) (us|usa|uk|eu|canada|australia)\b/i,
  /\bremote.*us only\b/i, /\bus.*remote.*only\b/i,
  /\bno international\b/i, /\bnot open to international\b/i,
  /\bdoes not (support|sponsor) (work )?visa\b/i,
  /\bopen to (us|usa|uk|eu|canadian|australian) (residents|citizens|applicants) only\b/i
];
return $input.all().map(item => {
  const job = item.json;
  const text = [job.description || '', job.location_text || '', job.job_title || ''].join(' ');
  let hard_filter_passed = true;
  let hard_reject_reason = '';
  for (const p of REJECT) {
    if (p.test(text)) {
      hard_filter_passed = false;
      hard_reject_reason = `Hard filter: ${p.toString()}`;
      break;
    }
  }
  return { json: { ...job, hard_filter_passed, hard_reject_reason } };
});

const item = $input.item;
const job = { ...item.json };
const aiText = job.message?.content || job.choices?.[0]?.message?.content || JSON.stringify(job);
let ai = {};
try {
  const match = aiText.match(/\{[\s\S]*\}/);
  if (match) ai = JSON.parse(match[0]);
} catch(e) {
  ai = { taiwan_eligible: 'unclear', reason: 'parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
}
return {
  json: {
    ...job,
    taiwan_eligible: ai.taiwan_eligible || 'unclear',
    taiwan_reason: ai.reason || '',
    location_risk: ai.location_risk || 'medium',
    timezone_risk: ai.timezone_risk || 'medium',
    contractor_possible: ai.contractor_possible || 'unclear',
    ai_decision: ai.decision || 'manual_check'
  }
};

const job = { ...$input.item.json };
const text = [job.description || '', job.tags || '', job.job_title || ''].join(' ').toLowerCase();

const asyncHigh = /\basync\b|\basynchronous\b|async.first|no.meetings|own.hours/.test(text);
const asyncMed  = /flexible.hours|flexible.schedule|distributed.team|remote.first|work.across.time.zones|results.oriented|output.focused/.test(text);
const tzRejected = /strict.9.to.5|9-5 required|fixed.us.hours|fixed.est|fixed.pst|fixed.cet|daily.live.calls|must.overlap.full.business/.test(text);

let async_level = 'unknown';
let async_score = 5;
if (tzRejected) { async_level = 'low'; async_score = 0; }
else if (asyncHigh) { async_level = 'high'; async_score = 25; }
else if (asyncMed) { async_level = 'medium'; async_score = 20; }

return {
  json: {
    ...job,
    async_level,
    async_score,
    tz_rejected: tzRejected
  }
};

const job = { ...$input.item.json };
const titleText = (job.job_title || '').toLowerCase();
const fullText = [job.description || '', job.tags || '', titleText].join(' ').toLowerCase();

// === TAIWAN ELIGIBILITY (0-40) ===
let taiwan_score = 0;
const eligible = job.taiwan_eligible || '';
if (eligible === 'yes') {
  if (/worldwide|work from anywhere|global remote|contractor|deel|oyster|eor/.test(fullText)) taiwan_score = 40;
  else if (/apac/.test(fullText)) taiwan_score = 30;
  else taiwan_score = 20;
} else if (eligible === 'unclear') {
  taiwan_score = 20;
}

// === ASYNC FIT (0-25) — already in async_score ===
const async_score = job.async_score || 0;

// === ROLE FIT (0-25) ===
const primaryRoles = /data analyst|data scientist|bi analyst|business intelligence|marketing analyst|growth analyst|performance marketing|ai marketing|ai automation|martech|machine learning|analytics engineer|junior data/;
const adjRoles = /analyst|data|marketing|growth|automation|intelligence|reporting|seo|ppc|paid media/;
let role_score = 0;
let role_category = 'Other';
if (primaryRoles.test(titleText)) {
  role_score = 25;
  if (/data scientist|machine learning/.test(titleText)) role_category = 'Data Science';
  else if (/data analyst|bi analyst|business intelligence|analytics/.test(titleText)) role_category = 'Data Analytics';
  else if (/marketing analyst|growth analyst|performance/.test(titleText)) role_category = 'Marketing Analytics';
  else if (/ai|automation|martech/.test(titleText)) role_category = 'AI/Automation';
  else role_category = 'Data';
} else if (primaryRoles.test(fullText)) {
  role_score = 15; role_category = 'Adjacent';
} else if (adjRoles.test(titleText)) {
  role_score = 10; role_category = 'Adjacent';
}

// === SALARY (0-25) ===
const salStr = String(job.salary || '');
let salary_score = 0;
if (salStr.trim()) {
  salary_score = 10;
  const nums = salStr.match(/[\d,]+/g);
  if (nums) {
    const max = Math.max(...nums.map(n => parseInt(n.replace(/,/g, ''))));
    if (max >= 5000 || (salStr.toLowerCase().includes('k') && max >= 5)) salary_score = 25;
    else if (max >= 3000 || (salStr.toLowerCase().includes('k') && max >= 3)) salary_score = 15;
  }
}

const score = taiwan_score + async_score + role_score + salary_score;

const reasons = [];
if (eligible === 'yes') reasons.push('Taiwan eligible');
if (job.async_level === 'high') reasons.push('fully async');
if (role_score === 25) reasons.push('perfect role match');
if (salary_score >= 25) reasons.push('strong salary ($5k+/mo)');
else if (salary_score >= 15) reasons.push('good salary ($3k+/mo)');

return {
  json: {
    ...job,
    score,
    taiwan_score,
    role_score,
    salary_score,
    role_category,
    why_good_fit: reasons.join(' | ') || 'Meets remote criteria',
    application_status: eligible === 'unclear' ? 'manual_check' : 'not_applied',
    notes: ''
  }
};

