const today = new Date().toISOString().split('T')[0];
const all = $input.all().map(i => i.json);

const filtered = all
  .filter(j => j._type === 'filtered' && String(j.date_found || '').startsWith(today))
  .sort((a, b) => (Number(b.score) || 0) - (Number(a.score) || 0));

const rejected = all
  .filter(j => j._type === 'rejected' && String(j.date_rejected || j.date_found || '').startsWith(today));

const topJobs = filtered.slice(0, 10);
const manualCheck = filtered.filter(j => j.taiwan_eligible === 'unclear' && (Number(j.score) || 0) >= 75);

const counts = { 'US only': 0, 'EU only': 0, 'Hybrid': 0, 'Timezone': 0, 'Low score': 0, 'AI reject': 0, 'Other': 0 };
for (const j of rejected) {
  const r = String(j.reason || '').toLowerCase();
  if (/us only|usa|united states/.test(r)) counts['US only']++;
  else if (/eu|europe/.test(r)) counts['EU only']++;
  else if (/hybrid|onsite/.test(r)) counts['Hybrid']++;
  else if (/timezone|tz/.test(r)) counts['Timezone']++;
  else if (/low score|score/.test(r)) counts['Low score']++;
  else if (/ai:/.test(r)) counts['AI reject']++;
  else counts['Other']++;
}

const dateStr = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Taipei'
});

let msg = `Daily Taiwan Eligible Async Remote Jobs\n${dateStr}\n`;
msg += `${'='.repeat(50)}\n\n`;
msg += `Summary: ${topJobs.length} qualifying jobs | ${rejected.length} rejected today\n\n`;

if (topJobs.length === 0) {
  msg += 'No qualifying jobs found today. Check sources or broaden keywords.\n\n';
} else {
  msg += 'TOP JOBS TODAY\n' + '-'.repeat(40) + '\n\n';
  topJobs.forEach((j, i) => {
    msg += `${i + 1}. ${j.job_title || 'Unknown Role'}\n`;
    msg += `   Company:         ${j.company || 'Unknown'}\n`;
    msg += `   Score:           ${j.score || 0}/100\n`;
    msg += `   Taiwan Eligible: ${j.taiwan_eligible || 'unclear'}\n`;
    msg += `   Reason:          ${j.taiwan_reason || '-'}\n`;
    msg += `   Async Level:     ${j.async_level || 'unknown'}\n`;
    msg += `   Timezone Risk:   ${j.timezone_risk || 'medium'}\n`;
    msg += `   Salary:          ${j.salary || 'Not listed'}\n`;
    msg += `   Role:            ${j.role_category || '-'}\n`;
    msg += `   Why Jerry Fits:  ${j.why_good_fit || '-'}\n`;
    msg += `   Apply:           ${j.job_url || '-'}\n\n`;
  });
}

if (manualCheck.length > 0) {
  msg += '\nMANUAL CHECK (Taiwan Eligibility Unclear, High Score)\n' + '-'.repeat(40) + '\n';
  manualCheck.slice(0, 5).forEach(j => {
    msg += `* ${j.job_title} @ ${j.company} — Score: ${j.score}\n`;
    msg += `  ${j.job_url}\n`;
    msg += `  Note: ${j.taiwan_reason || 'Needs manual review'}\n\n`;
  });
}

msg += '\nREJECTION SUMMARY\n' + '-'.repeat(40) + '\n';
for (const [reason, count] of Object.entries(counts)) {
  if (count > 0) msg += `${reason.padEnd(20)} ${count}\n`;
}

const subject = `[Jerry Jobs] ${dateStr} — ${topJobs.length} found${topJobs.length > 0 ? ', top score: ' + (topJobs[0].score || 0) : ''}`;
return [{ json: { message: msg, subject } }];
